// Day 09 - Ternary, Optional Chaining, Nullish Coalescing

// ========== Ternary Operator ==========
// condition ? trueValue : falseValue
const age = 20;
const status = age >= 18 ? "Adult" : "Minor";
console.log(status); // Adult

const marks = 75;
const grade = marks >= 90 ? "A" : marks >= 75 ? "B" : marks >= 60 ? "C" : "D";
console.log(grade); // B

// React me bahut use:
// {isLoggedIn ? <Dashboard /> : <Login />}

// ========== Optional Chaining (?.) ==========
// Agar beech me null/undefined ho to error nahi, undefined return
const user = {
  name: "Aman",
  address: {
    city: "Delhi"
    // street nahi hai
  }
};

console.log(user.address.city);           // Delhi
console.log(user.address?.street);        // undefined (error nahi)
console.log(user.contact?.phone);         // undefined
console.log(user.contact?.phone?.number); // undefined - chain

// Array / function pe bhi
const arr = null;
console.log(arr?.[0]);                    // undefined

const fn = null;
console.log(fn?.());                      // undefined

// ========== Nullish Coalescing (??) ==========
// Sirf null ya undefined hone par default value
// (0, "", false ko as-is rehne deta hai - || se farq)

const count = 0;
console.log(count || 10);   // 10  (kyunki 0 falsy hai)
console.log(count ?? 10);   // 0   (kyunki 0 nullish nahi hai)

const name = "";
console.log(name || "Guest");  // Guest
console.log(name ?? "Guest");  // "" (empty string rehne do)

const data = null;
console.log(data ?? "Default"); // Default

// Combined
const city = user.address?.city ?? "Unknown";
console.log(city); // Delhi

