// Day 11 - Mini Project: Number Analyzer
// map, filter, reduce, arrow functions sab use

const numbers = [5, 12, 8, 3, 20, 7, 15, 2, 9, 11];

console.log("Original:", numbers);

// 1. Even numbers
const evens = numbers.filter(n => n % 2 === 0);
console.log("Even numbers:", evens);

// 2. Odd numbers
const odds = numbers.filter(n => n % 2 !== 0);
console.log("Odd numbers:", odds);

// 3. Squares
const squares = numbers.map(n => n * n);
console.log("Squares:", squares);

// 4. Sum
const sum = numbers.reduce((acc, n) => acc + n, 0);
console.log("Sum:", sum);

// 5. Average
const avg = sum / numbers.length;
console.log("Average:", avg);

// 6. Max & Min
const max = numbers.reduce((a, b) => (a > b ? a : b));
const min = numbers.reduce((a, b) => (a < b ? a : b));
console.log("Max:", max, "Min:", min);

// 7. Even count & Odd count
const evenCount = evens.length;
const oddCount = odds.length;
console.log(`Even: ${evenCount}, Odd: ${oddCount}`);

// Sundar output
console.log(`
======= NUMBER ANALYZER =======
Numbers : ${numbers.join(", ")}
Evens   : ${evens.join(", ")}
