import React, { useState } from "react";

function Counter() {
  // useState(initialValue) → [currentValue, setterFunction]
  const [count, setCount] = useState(0);
  // count = abhi ki value
  // setCount = value change karne ka function
  // 0 = shuruaati value

  // Jab setCount call hota hai → React component ko re-render karta hai

  const increment = () => {
    // Functional update - jab naya value purane pe depend kare
    setCount((prev) => prev + 1);
    // setCount(count + 1) bhi chalega lekin rapid clicks me issue ho sakta hai
  };

  const decrement = () => {
    setCount((prev) => prev - 1);
  };

  const reset = () => {
    setCount(0);
  };

  return (
    <div style={{ textAlign: "center", marginTop: 40 }}>
      <h1>Count: {count}</h1>
      <button onClick={increment}>+ Increment</button>
      <button onClick={decrement} style={{ margin: "0 8px" }}>
        - Decrement
      </button>
      <button onClick={reset}>Reset</button>
    </div>
  );
}

export default Counter;

