// Day 25 - State with Arrays (Immutable updates)

import React, { useState } from "react";

function TodoList() {
  const [todos, setTodos] = useState([]);
  const [input, setInput] = useState("");

  // ADD - spread se naya array
  const addTodo = () => {
    if (input.trim() === "") return;  // empty mat add karo

    const newTodo = {
      id: Date.now(),       // unique id
      text: input,
      done: false
    };

    // GALAT: todos.push(newTodo)  ← mutation, React nahi samjhega
    // SAHI:
    setTodos([...todos, newTodo]);  // purana + naya
    setInput("");
  };

  // DELETE - filter se naya array (jo id match nahi karta)
  const deleteTodo = (id) => {
    setTodos(todos.filter((todo) => todo.id !== id));
  };

  // TOGGLE done - map se naya array, matching item update
  const toggleTodo = (id) => {
    setTodos(
      todos.map((todo) =>
        todo.id === id ? { ...todo, done: !todo.done } : todo
      )
    );
  };

  return (
    <div style={{ maxWidth: 400, margin: "40px auto" }}>
      <h2>Todo (Array State)</h2>

      <input
        value={input}
        onChange={(e) => setInput(e.target.value)}
        placeholder="Naya todo..."
      />
      <button onClick={addTodo}>Add</button>

      <ul>
        {todos.map((todo) => (
          <li key={todo.id}>
            <span
              onClick={() => toggleTodo(todo.id)}
              style={{
                textDecoration: todo.done ? "line-through" : "none",
                cursor: "pointer"
              }}
            >
              {todo.text}
            </span>
            <button onClick={() => deleteTodo(todo.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default TodoList;

