// Day 27 - Basic Form Validation
import React, { useState } from "react";

function SignupForm() {
  const [form, setForm] = useState({ name: "", email: "", password: "" });
  const [errors, setErrors] = useState({});

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm(prev => ({ ...prev, [name]: value }));
    // typing pe error clear
    setErrors(prev => ({ ...prev, [name]: "" }));
  };

  const validate = () => {
    const newErrors = {};
    if (!form.name.trim()) newErrors.name = "Name zaroori hai";
    if (!form.email.trim()) newErrors.email = "Email zaroori hai";
    else if (!/\S+@\S+\.\S+/.test(form.email)) newErrors.email = "Email sahi nahi hai";
    if (!form.password) newErrors.password = "Password zaroori hai";
    else if (form.password.length < 6) newErrors.password = "Kam se kam 6 characters";
    return newErrors;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const newErrors = validate();
    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }
    alert("Form valid! " + JSON.stringify(form));
  };

  return (
    <form onSubmit={handleSubmit} style={{ maxWidth: 360, margin: "40px auto" }}>
      <h2>Signup</h2>
      <div>
        <input name="name" value={form.name} onChange={handleChange} placeholder="Name" />
        {errors.name && <p style={{ color: "red" }}>{errors.name}</p>}
      </div>
      <div>
        <input name="email" value={form.email} onChange={handleChange} placeholder="Email" />
        {errors.email && <p style={{ color: "red" }}>{errors.email}</p>}
      </div>
      <div>
        <input name="password" type="password" value={form.password} onChange={handleChange} placeholder="Password" />
        {errors.password && <p style={{ color: "red" }}>{errors.password}</p>}
      </div>
      <button type="submit">Submit</button>
    </form>
  );
}
export default SignupForm;

