  // });

  // 2. Sirf mount pe ek baar (empty array)
  useEffect(() => {
    console.log("Component mount hua (ek baar)");
    document.title = "useEffect Demo";
  }, []); // [] = koi dependency nahi → sirf pehli baar

  // 3. Jab count change ho
  useEffect(() => {
    console.log("Count badla:", count);
    document.title = `Count: ${count}`;
  }, [count]); // count change hone par dubara chalo

  // 4. Cleanup example - timer
  useEffect(() => {
    const id = setInterval(() => {
      console.log("Tick...");
    }, 2000);

    // cleanup - component unmount ya effect re-run se pehle
    return () => {
      clearInterval(id);
      console.log("Timer clear kar diya");
    };
  }, []);

  return (
    <div>
      <h1>Count: {count}</h1>
