// Day 43 - Context API - Theme Example

import React, { createContext, useContext, useState } from "react";

// 1. Context banao
const ThemeContext = createContext();

// 2. Provider component
function ThemeProvider({ children }) {
  const [theme, setTheme] = useState("light");

  const toggleTheme = () => {
    setTheme((prev) => (prev === "light" ? "dark" : "light"));
  };

  // value me jo bhejoge wo consumers ko milega
  return (
    <ThemeContext.Provider value={{ theme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
}

// 3. Custom hook - aasani se use karne ke liye
function useTheme() {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error("useTheme sirf ThemeProvider ke andar use karo");
  }
  return context;
}

// 4. Koi bhi child component
function Navbar() {
  const { theme, toggleTheme } = useTheme();

  return (
    <nav
      style={{
        background: theme === "light" ? "#eee" : "#333",
        color: theme === "light" ? "#000" : "#fff",
        padding: 16
      }}
    >
      <span>Theme: {theme}</span>
      <button onClick={toggleTheme} style={{ marginLeft: 12 }}>
        Toggle Theme
      </button>
    </nav>
  );
}

function Content() {
  const { theme } = useTheme();
  return (
    <div style={{ padding: 20, color: theme === "dark" ? "#fff" : "#000" }}>
      <h1>Content Area</h1>
      <p>Abhi theme hai: {theme}</p>
    </div>
  );
}

// 5. App
function App() {
  return (
    <ThemeProvider>
      <div style={{ minHeight: "100vh", background: "#fafafa" }}>
        <Navbar />
        <Content />
      </div>
    </ThemeProvider>
  );
}

export default App;

