// Day 46 - useReducer Basics

import React, { useReducer } from "react";

// 1. Initial state
const initialState = { count: 0 };

// 2. Reducer function - pure function
// state + action → new state
function reducer(state, action) {
  switch (action.type) {
    case "INCREMENT":
      return { count: state.count + 1 };
    case "DECREMENT":
      return { count: state.count - 1 };
    case "RESET":
      return { count: 0 };
    case "ADD":
      // action.payload me extra data
      return { count: state.count + action.payload };
    default:
      return state; // unknown action → state same
  }
}

function Counter() {
  // 3. useReducer(reducer, initialState)
  // state = current state
  // dispatch = action bhejne ka function
  const [state, dispatch] = useReducer(reducer, initialState);

  return (
    <div style={{ textAlign: "center", marginTop: 40 }}>
      <h1>Count: {state.count}</h1>

      <button onClick={() => dispatch({ type: "INCREMENT" })}>+</button>
      <button onClick={() => dispatch({ type: "DECREMENT" })} style={{ margin: 8 }}>
        -
      </button>
      <button onClick={() => dispatch({ type: "RESET" })}>Reset</button>
      <button onClick={() => dispatch({ type: "ADD", payload: 5 })} style={{ margin: 8 }}>
        +5
      </button>
    </div>
  );
}

export default Counter;

