// Day 51 - useRef

import React, { useRef, useState, useEffect } from "react";

function UseRefDemo() {
  // 1. DOM element access
  const inputRef = useRef(null);
  // inputRef.current → actual DOM node (baad me)

  const focusInput = () => {
    inputRef.current.focus();      // input pe focus
    inputRef.current.select();     // text select
  };

  // 2. Mutable value jo re-render NA trigger kare
  const renderCount = useRef(0);
  const [text, setText] = useState("");

  useEffect(() => {
    renderCount.current = renderCount.current + 1;
    // ye change se re-render nahi hota
  });

  // 3. Previous value track karna
  const prevText = useRef("");
  useEffect(() => {
    prevText.current = text;
  }, [text]);

  return (
    <div style={{ padding: 20 }}>
      <h2>useRef Demo</h2>

      <input ref={inputRef} placeholder="Yahan type karo" />
      <button onClick={focusInput}>Focus Input</button>

      <p>Render count: {renderCount.current}</p>

      <input
        value={text}
        onChange={(e) => setText(e.target.value)}
        placeholder="Text"
      />
      <p>Current: {text}</p>
      <p>Previous: {prevText.current}</p>
    </div>
  );
}

export default UseRefDemo;

